/** Source: egg_hatch.c → CB2_EggHatch */
export const CB2_EggHatch: CB2Callback = (rt) => {
  let species = 0;
      let gender = 0;
      let personality = 0;

      switch (sEggHatchData.state)
      {
      case 0:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 16, 0, "RGB_BLACK");
          sEggHatchData.eggSpriteId = rt.CreateSpriteFromTemplate('sSpriteTemplate_Egg',  EGG_X, EGG_Y, 5);
          ShowBg(0);
          ShowBg(1);
          sEggHatchData.state++;
          rt.CreateTask((t) => Task_EggHatchPlayBGM(t, rt), 5);
          break;
      case 1:
          if (!rt.gPaletteFade.active)
          {
              FillWindowPixelBuffer(sEggHatchData.windowId, PIXEL_FILL(0));
              sEggHatchData.delayTimer = 0;
              sEggHatchData.state++;
          }
          break;
      case 2:
          if (++sEggHatchData.delayTimer > 30)
          {
               
              sEggHatchData.state++;
              rt.setSpriteCallback(sEggHatchData.eggSpriteId, SpriteCB_Egg_Shake1);
          }
          break;
      case 3:
           
          if (_gs(rt, sEggHatchData.eggSpriteId).callback == SpriteCallbackDummy)
          {
              species = GetMonData(gPlayerParty[sEggHatchData.eggPartyId], MON_DATA_SPECIES);
              DoMonFrontSpriteAnimation(_gs(rt, sEggHatchData.monSpriteId), species, false, 1);
              sEggHatchData.state++;
          }
          break;
      case 4:
           
          if (_gs(rt, sEggHatchData.monSpriteId).callback == SpriteCallbackDummy)
              sEggHatchData.state++;
          break;
      case 5:
           
          GetMonNickname2(gPlayerParty[sEggHatchData.eggPartyId], gStringVar1);
          StringExpandPlaceholders(gStringVar4, gText_HatchedFromEgg);
          EggHatchPrintMessage(sEggHatchData.windowId, gStringVar4, 0, 3, TEXT_SKIP_DRAW);
          PlayFanfare(MUS_EVOLVED);
          sEggHatchData.state++;
          PutWindowTilemap(sEggHatchData.windowId);
          CopyWindowToVram(sEggHatchData.windowId, COPYWIN_FULL);
          break;
      case 6:
          if (IsFanfareTaskInactive())
              sEggHatchData.state++;
          break;
      case 7:  
          if (IsFanfareTaskInactive())
              sEggHatchData.state++;
          break;
      case 8:
           
          GetMonNickname2(gPlayerParty[sEggHatchData.eggPartyId], gStringVar1);
          StringExpandPlaceholders(gStringVar4, gText_NicknameHatchPrompt);
          EggHatchPrintMessage(sEggHatchData.windowId, gStringVar4, 0, 2, 1);
          sEggHatchData.state++;
          break;
      case 9:
           
          if (!IsTextPrinterActive(sEggHatchData.windowId))
          {
              LoadUserWindowBorderGfx(sEggHatchData.windowId, 0x140, BG_PLTT_ID(14));
              CreateYesNoMenu(sYesNoWinTemplate, 0x140, 0xE, 0);
              sEggHatchData.state++;
          }
          break;
      case 10:
           
          switch (Menu_ProcessInputNoWrapClearOnChoose())
          {
          case 0:  
              GetMonNickname2(gPlayerParty[sEggHatchData.eggPartyId], gStringVar3);
              species = GetMonData(gPlayerParty[sEggHatchData.eggPartyId], MON_DATA_SPECIES);
              gender = GetMonGender(gPlayerParty[sEggHatchData.eggPartyId]);
              personality = GetMonData(gPlayerParty[sEggHatchData.eggPartyId], MON_DATA_PERSONALITY, 0);
              DoNamingScreen(NAMING_SCREEN_NICKNAME, gStringVar3, species, gender, personality, EggHatchSetMonNickname);
              break;
          case 1:  
          case MENU_B_PRESSED:
              sEggHatchData.state++;
              break;
          }
          break;
      case 11:
          rt.BeginNormalPaletteFade("PALETTES_ALL", 0, 0, 16, "RGB_BLACK");
          sEggHatchData.state++;
          break;
      case 12:
          if (!rt.gPaletteFade.active)
          {
              FreeMonSpritesGfx();
              RemoveWindow(sEggHatchData.windowId);
              UnsetBgTilemapBuffer(0);
              UnsetBgTilemapBuffer(1);
              Free(sEggHatchData);
              /* TODO scene transition: SetMainCallback2(CB2_ReturnToField) */;
          }
          break;
      }

      RunTasks();
      RunTextPrinters();
      AnimateSprites();
      BuildOamBuffer();
      UpdatePaletteFade();
};
